<script setup lang="ts">
import { RefreshCw } from "lucide-vue-next";import { formatDate } from "~/utils/format";
interface Audit {id:string;action:string;entity:string;entityId:string|null;previousData:unknown;newData:unknown;metadata:unknown;createdAt:string;user:{name:string;email:string}|null}
const api=useApi();const items=ref<Audit[]>([]),loading=ref(true),page=ref(1),pages=ref(1),entity=ref(""),action=ref(""),message=ref("");
async function load(){loading.value=true;try{const res=await api.get<{items:Audit[];pagination:{totalPages:number}}>("/auditoria",{page:page.value,pageSize:50,entity:entity.value||undefined,action:action.value||undefined});items.value=res.items;pages.value=res.pagination.totalPages;}catch(cause){message.value=cause instanceof Error?cause.message:"Erro ao carregar auditoria.";}finally{loading.value=false;}}
watch([page,entity,action],load);onMounted(load);
</script>
<template><section class="surface"><header class="surface-header"><div><h2>Auditoria</h2><p>Trilha de eventos administrativos.</p></div><div class="toolbar"><label class="field"><span>Entidade</span><input v-model="entity"/></label><label class="field"><span>Ação</span><input v-model="action"/></label><button class="btn btn-icon" @click="load"><RefreshCw :size="16"/></button></div></header><div class="surface-body stack"><p v-if="message" class="notice error">{{message}}</p><div v-if="loading" class="loading-state"><div class="spinner"/></div><div v-else class="table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Usuário</th><th>Ação</th><th>Entidade</th><th>ID</th><th>Alteração</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td>{{formatDate(item.createdAt,true)}}</td><td>{{item.user?.name||'Sistema'}}</td><td><span class="badge info">{{item.action}}</span></td><td>{{item.entity}}</td><td>{{item.entityId||'—'}}</td><td><details><summary>Visualizar</summary><pre class="max-w-xl overflow-auto text-xs">{{JSON.stringify({anterior:item.previousData,novo:item.newData,metadata:item.metadata},null,2)}}</pre></details></td></tr></tbody></table></div><div class="toolbar justify-end"><button class="btn small" :disabled="page<=1" @click="page--">Anterior</button><span class="text-xs">Página {{page}} de {{pages}}</span><button class="btn small" :disabled="page>=pages" @click="page++">Próxima</button></div></div></section></template>
